config.renderFunction:
function render(ctx, width, height, state) {
  const p = state.powerRatio;
  const db = 10 * Math.log10(p);
  const dbm = db + 30;
  const voltDb = 20 * Math.log10(Math.sqrt(p));

  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(0, 0, width, height);

  ctx.font = 'bold 15px sans-serif';
  ctx.fillStyle = '#38bdf8';
  ctx.fillText('Linear Ratio: ' + Number(p).toLocaleString() + ' : 1', 30, 40);

  ctx.font = 'bold 20px monospace';
  ctx.fillStyle = '#34d399';
  ctx.fillText(db.toFixed(2) + ' dB (Power Gain)', 30, 75);

  ctx.font = '13px sans-serif';
  ctx.fillStyle = '#94a3b8';
  ctx.fillText('Equivalent absolute power for 1 mW input: ' + dbm.toFixed(2) + ' dBm', 30, 100);

  const barY1 = 150;
  const barY2 = 230;
  const maxW = width - 80;

  ctx.font = '12px sans-serif';
  ctx.fillStyle = '#cbd5e1';
  ctx.fillText('Linear Scale (1 to 100,000) — Severe saturation:', 30, barY1 - 10);

  ctx.fillStyle = '#1e293b';
  ctx.fillRect(30, barY1, maxW, 24);
  ctx.fillStyle = '#f43f5e';
  const linW = Math.max(4, (p / 100000) * maxW);
  ctx.fillRect(30, barY1, linW, 24);

  ctx.fillStyle = '#cbd5e1';
  ctx.fillText('Logarithmic Scale (0 dB to 50 dB) — Perfectly uniform resolution:', 30, barY2 - 10);

  ctx.fillStyle = '#1e293b';
  ctx.fillRect(30, barY2, maxW, 24);
  ctx.fillStyle = '#10b981';
  const logW = Math.max(4, (db / 50) * maxW);
  ctx.fillRect(30, barY2, logW, 24);

  ctx.fillStyle = '#64748b';
  ctx.font = '11px monospace';
  ctx.fillText('0 dB (1x)', 30, barY2 + 40);
  ctx.fillText('10 dB (10x)', 30 + maxW * 0.2 - 25, barY2 + 40);
  ctx.fillText('20 dB (100x)', 30 + maxW * 0.4 - 30, barY2 + 40);
  ctx.fillText('30 dB (1kx)', 30 + maxW * 0.6 - 25, barY2 + 40);
  ctx.fillText('40 dB (10kx)', 30 + maxW * 0.8 - 30, barY2 + 40);
  ctx.fillText('50 dB (100kx)', 30 + maxW - 35, barY2 + 40);
}
